{
  "service": "gateway",
  "description": "gateway edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8080
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "notifications",
      "host": "notifications.internal",
      "port": 8933,
      "weight": 1,
      "health_check": "/healthz"
    },
    {
      "name": "carts",
      "host": "carts.internal",
      "port": 7862,
      "weight": 6,
      "health_check": "/healthz"
    },
    {
      "name": "orders",
      "host": "orders.internal",
      "port": 7418,
      "weight": 5,
      "health_check": "/healthz"
    },
    {
      "name": "payments",
      "host": "payments.internal",
      "port": 7374,
      "weight": 5,
      "health_check": "/healthz"
    },
    {
      "name": "accounts",
      "host": "accounts.internal",
      "port": 7988,
      "weight": 10,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/notifications/refunds",
      "upstream": "notifications",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 2000,
      "retries": 1
    },
    {
      "path": "/api/v1/accounts/tokens",
      "upstream": "accounts",
      "methods": [
        "POST"
      ],
      "timeout_ms": 2500,
      "retries": 0
    },
    {
      "path": "/api/v1/notifications/labels",
      "upstream": "notifications",
      "methods": [
        "GET"
      ],
      "timeout_ms": 5000,
      "retries": 0
    },
    {
      "path": "/api/v1/carts/items",
      "upstream": "carts",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 3000,
      "retries": 0
    },
    {
      "path": "/api/v1/accounts/export",
      "upstream": "accounts",
      "methods": [
        "GET"
      ],
      "timeout_ms": 1000,
      "retries": 2
    },
    {
      "path": "/api/v1/orders/history",
      "upstream": "orders",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 1000,
      "retries": 3
    },
    {
      "path": "/api/v1/carts/history",
      "upstream": "carts",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 2500,
      "retries": 3
    },
    {
      "path": "/api/v1/carts/quotes",
      "upstream": "carts",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 1500,
      "retries": 2
    },
    {
      "path": "/api/v1/payments/status",
      "upstream": "payments",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 1000,
      "retries": 3
    },
    {
      "path": "/api/v1/notifications/settings",
      "upstream": "notifications",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 5000,
      "retries": 1
    },
    {
      "path": "/api/v1/notifications/quotes",
      "upstream": "notifications",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 5000,
      "retries": 2
    },
    {
      "path": "/api/v1/notifications/history",
      "upstream": "notifications",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 2500,
      "retries": 1
    },
    {
      "path": "/api/v1/payments/settings",
      "upstream": "payments",
      "methods": [
        "GET"
      ],
      "timeout_ms": 5000,
      "retries": 2
    }
  ],
  "banner": "Say \"hello\" to the \\ backslash",
  "path_regex": "^/api/v[0-9]+/\\w+(\\.json)?$",
  "cert_dir": "C:\\ProgramData\\edge\\certs",
  "locale_note": "ñ, 東京, Zürich, 🚀",
  "log_line_format": "{\"ts\":\"%t\",\"msg\":\"%m\"}\t%n"
}

